/// <summary>
/// This method executes when update happens
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
/// <returns></returns>
public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean     ret;
    boolean     qtyFieldUpdated;
    boolean     metCancelSalesLine;
    SalesLine   salesLineOrig, salesLine;
    METSalesOrderLinePEEntity   metSalesOrderLinePEEntity;


    if (_dataSourceCtx.name() == dataentitydatasourcestr(METSalesOrderLinePECDSEntity, METSalesOrderLinePEEntity) &&
        _entityCtx.isDatabaseOperationUpdate())
    {
        metSalesOrderLinePEEntity   = _dataSourceCtx.getBuffer();

        salesLineOrig = SalesLine::findInventTransId(metSalesOrderLinePEEntity.InventTransId, true).orig();

        if (this.SalesQty != salesLineOrig.SalesQty)
        {
            qtyFieldUpdated = true;
        }
    }
    if (this.METStatusCancelled)
    {
        metCancelSalesLine  = true;
    }

    ret = super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataentitydatasourcestr(METSalesOrderLinePECDSEntity, METSalesOrderLinePEEntity) &&
        _entityCtx.isDatabaseOperationUpdate())
    {
        metSalesOrderLinePEEntity   = _dataSourceCtx.getBuffer();

        salesLine = SalesLine::findInventTransId(metSalesOrderLinePEEntity.InventTransId, true);

        if (metCancelSalesLine)
        {
            salesLine.metCancelSalesOrderLine();
            this.metUpdateLineindicator(salesLine, true);
        }
        if (qtyFieldUpdated)
        {
            this.metUpdateLineindicator(salesLine, false);
        }
    }

    return ret;
}

/// <summary>
/// This method is used to update Line Indicator
/// </summary>
/// <param name = "_salesLine">SalesLine</param>
/// <param name = "_doCancel">boolean</param>
public void metUpdateLineindicator(SalesLine _salesLine, boolean _doCancel)
{
    METSalesLine    metSalesLineUpdate;
    SalesLine       salesLineUpdate;

    try
    {
        ttsbegin;
        if(_doCancel)
        {
            update_recordset metSalesLineUpdate
                setting
                LineIndicator = METLineIndicator::D
                join salesLineUpdate
                where metSalesLineUpdate.SalesLine == salesLineUpdate.RecId
                && salesLineUpdate.SalesStatus == SalesStatus::Canceled
                && salesLineUpdate.RecId == _salesLine.RecId;
        }
        else
        {

            update_recordset metSalesLineUpdate
                setting
                LineIndicator = METLineIndicator::A
                join salesLineUpdate
                where metSalesLineUpdate.SalesLine == salesLineUpdate.RecId
                && salesLineUpdate.SalesId == _salesLine.SalesId
                && salesLineUpdate.SalesStatus != SalesStatus::Canceled
                && salesLineUpdate.RecId == _salesLine.RecId;


            metSalesLineUpdate.clear();
            salesLineUpdate.clear();
            update_recordset metSalesLineUpdate
                setting
                LineIndicator = METLineIndicator::U
                join salesLineUpdate
                where metSalesLineUpdate.SalesLine == salesLineUpdate.RecId
                && salesLineUpdate.SalesId == _salesLine.SalesId
                && metSalesLineUpdate.LineIndicator != METLineIndicator::A
                && salesLineUpdate.SalesStatus != SalesStatus::Canceled
                && salesLineUpdate.RecId != _salesLine.RecId;
        }
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch
    {
        throw error("@MET:UnhandledError");
    }
}

/// <summary>
/// This method executes when insert happens
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
/// <returns></returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;
    boolean metCancelSalesLine;
    METSalesOrderLinePEEntity   metSalesOrderLinePEEntity;

    if (_dataSourceCtx.name() == dataentitydatasourcestr(METSalesOrderLinePECDSEntity, METSalesOrderLinePEEntity) &&
        _entityCtx.isDatabaseOperationInsert())
    {
        if (this.METStatusCancelled)
        {
            metCancelSalesLine  = true;
        }
    }

    ret = super(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataentitydatasourcestr(METSalesOrderLinePECDSEntity, METSalesOrderLinePEEntity) &&
        _entityCtx.isDatabaseOperationInsert())
    {
        metSalesOrderLinePEEntity   = _dataSourceCtx.getBuffer();

        SalesLine salesLine = SalesLine::findInventTransId(metSalesOrderLinePEEntity.InventTransId, true);

        if(metCancelSalesLine)
        {
            this.LineIndicator = METLineIndicator::D;
            salesLine.metCancelSalesOrderLine();
        }
    }

    return ret;
}
